'use strict';

// MODULES //

var tape = require( 'tape' );
var Float64Results = require( '@stdlib/ml/base/kmeans/results/float64' );
var algorithmResolveEnum = require( '@stdlib/ml/base/kmeans/algorithm-resolve-enum' );
var metricResolveEnum = require( '@stdlib/ml/base/kmeans/metric-resolve-enum' );
var res2json = require( './../lib' );


// TESTS //

tape( 'main export is a function', function test( t ) {
	t.ok( true, __filename );
	t.strictEqual( typeof res2json, 'function', 'main export is a function' );
	t.end();
});

tape( 'the function serializes a results object to JSON', function test( t ) {
	var expected;
	var actual;
	var value;

	value = new Float64Results();
	value.replicates = 4;
	value.replicate = 2;
	value.metric = metricResolveEnum( 'sqeuclidean' );
	value.iterations = 10;
	value.algorithm = algorithmResolveEnum( 'lloyd' );
	value.inertia = 3.28;
	value.k = 4;
	value.samples = 10;
	value.features = 3;

	expected = {
		'replicates': 4,
		'replicate': 2,
		'metric': 'sqeuclidean',
		'iterations': 10,
		'algorithm': 'lloyd',
		'inertia': 3.28,
		'k': 4,
		'samples': 10,
		'features': 3,
		'method': 'K-means clustering'
	};

	actual = res2json( value );
	t.deepEqual( actual, expected, 'returns expected value' );
	t.end();
});
